import jwt

# Example of decoding a JWT with a flexible algorithm parameter
def decode_jwt_with_algorithm(token: str, key: str, algorithm: str = "HS256") -> dict:
    try:
        decoded = jwt.decode(token, key, algorithms=[algorithm])
        return decoded
    except jwt.PyJWTError:
        return {}

# Test the function with a sample token and key
sample_token = "your.jwt.token"
sample_key = "your_secret_key"
print(decode_jwt_with_algorithm(sample_token, sample_key, "HS256"))
